WITH END_TBL AS ( SELECT A.MACHINE_ID, A.PROCESS_ID, A.ACTIVITY_TYPE, A.TIMESTAMP AS END_TIME FROM ACTIVITY AS A WHERE A.ACTIVITY_TYPE = 'END'), START_TBL AS ( SELECT A.MACHINE_ID, A.PROCESS_ID, A.ACTIVITY_TYPE, A.TIMESTAMP AS START_TIME FROM ACTIVITY AS A WHERE A.ACTIVITY_TYPE = 'START' ), TIMEDIFF_TBL AS ( SELECT END_TBL.MACHINE_ID, END_TBL.PROCESS_ID, (END_TBL.END_TIME - START_TBL.START_TIME) AS TIMEDIFF FROM END_TBL LEFT JOIN START_TBL ON START_TBL.MACHINE_ID = END_TBL.MACHINE_ID AND START_TBL.PROCESS_ID = END_TBL.PROCESS_ID ), RUN_COUNT_TBL AS( SELECT TD.MACHINE_ID, COUNT(*) AS RUN_COUNT FROM TIMEDIFF_TBL AS TD GROUP BY TD.MACHINE_ID ), FINAL_TBL AS ( SELECT TD.MACHINE_ID, ROUND(SUM(TD.TIMEDIFF),3) AS TOTAL_RUN_TIME, RUN_COUNT_TBL.RUN_COUNT FROM TIMEDIFF_TBL AS TD LEFT JOIN RUN_COUNT_TBL ON RUN_COUNT_TBL.MACHINE_ID = TD.MACHINE_ID GROUP BY TD.MACHINE_ID) SELECT FINAL_TBL.MACHINE_ID, ROUND(FINAL_TBL.TOTAL_RUN_TIME / FINAL_TBL.RUN_COUNT, 3) AS PROCESSING_TIME FROM FINAL_TBL;

